const DAYS={"arms":{"label":"Biceps / Triceps","short":"Arms","groups":["Biceps","Triceps"],"icon":"💪","accent":"violet"},"legs":{"label":"Legs / Core","short":"Legs","groups":["Legs","Core"],"icon":"🦵","accent":"emerald"},"chest":{"label":"Chest / Shoulders","short":"Push","groups":["Chest","Shoulders"],"icon":"🏋️","accent":"amber"},"back":{"label":"Back / Traps","short":"Pull","groups":["Back","Traps"],"icon":"🪽","accent":"sky"},"cardio":{"label":"Cardio","short":"Cardio","groups":["Cardio","Cardio"],"icon":"❤️","accent":"rose"},"support":{"label":"Full-Body Support","short":"Support","groups":["Support","Support"],"icon":"⚙️","accent":"teal"},"rest":{"label":"Complete Rest","short":"Rest","groups":[],"icon":"🌙","accent":"slate"}};
const EXERCISE_MAP=Object.fromEntries(EXERCISES.map(e=>[e.id,e]));
const DAY_ORDER=['arms','legs','chest','back','cardio','support','rest'];
const WEEK_NAMES=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const STATE_KEY='forgefit-state-v1';
const APP_VERSION='1.2.0';
let deferredInstallPrompt=null;
let activeView='today';
let activeWorkoutTab='arms';
let builder={dayKey:'arms',name:'My Custom Arms',slots:[]};
let timerInterval=null;

const $=(s,p=document)=>p.querySelector(s);
const $$=(s,p=document)=>[...p.querySelectorAll(s)];
const clone=x=>JSON.parse(JSON.stringify(x));
const todayISO=()=>new Date().toISOString().slice(0,10);
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const fmtDate=(d,opts={})=>new Intl.DateTimeFormat('en-US',opts).format(new Date(d+'T12:00:00'));

function defaultState(){
 return {version:APP_VERSION,createdAt:todayISO(),baselineStart:todayISO(),schedule:clone(DAY_ORDER),history:[],customPresets:[],currentWorkout:null,checkins:{},settings:{theme:'dark',autoTimer:true,confirmBeforeFinish:true,weekStartsSunday:true}};
}
function loadState(){try{const raw=localStorage.getItem(STATE_KEY);return raw?{...defaultState(),...JSON.parse(raw),version:APP_VERSION}:defaultState()}catch(e){console.error(e);return defaultState()}}
let state=loadState();
function saveState(){localStorage.setItem(STATE_KEY,JSON.stringify(state));}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('show'),2200)}
function dayKeyToday(){return state.schedule[new Date().getDay()]||DAY_ORDER[new Date().getDay()]}
function currentWeekBounds(){const now=new Date();const start=new Date(now);start.setHours(0,0,0,0);start.setDate(now.getDate()-now.getDay());const end=new Date(start);end.setDate(start.getDate()+7);return [start,end]}
function weekHistory(){const [s,e]=currentWeekBounds();return state.history.filter(h=>{const d=new Date(h.date+'T12:00:00');return d>=s&&d<e})}
function presetById(id){return [...PRESETS,...state.customPresets].find(p=>p.id===id)}
function setsFor(item){return clone(item.sets||EXERCISE_MAP[item.id]?.defaultSets||[])}
function targetLabel(set,e){if(set.seconds!=null)return `${set.seconds} sec`;const w=set.weight==='BW'?'Bodyweight':`${set.weight} lb${e.unit==='each'?' each':''}`;return `${w} × ${set.reps}`}
function completeSets(h){return h.exercises?.reduce((n,e)=>n+e.sets.filter(s=>s.completed).length,0)||0}
function totalPlannedSets(p){return p.exercises.reduce((n,x)=>n+setsFor(x).length,0)}
function workoutDuration(h){return h.durationSec?Math.round(h.durationSec/60):0}

function applyTheme(){document.documentElement.dataset.theme=state.settings.theme;$('#themeBtn').textContent=state.settings.theme==='dark'?'☀':'☾';document.querySelector('meta[name=theme-color]').setAttribute('content',state.settings.theme==='dark'?'#0b1020':'#f4f6fb')}
function navigate(view){activeView=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));renderView(view);$('#mainContent').focus();scrollTo({top:0,behavior:'smooth'})}
function renderView(view){({today:renderToday,workouts:renderWorkouts,build:renderBuild,history:renderHistory,progress:renderProgress,settings:renderSettings}[view]||renderToday)()}

function renderToday(){
 const key=dayKeyToday(),day=DAYS[key],date=todayISO(),done=weekHistory();
 const todayDone=state.history.some(h=>h.date===date&&h.dayKey===key);
 const dayPresets=[...PRESETS,...state.customPresets].filter(p=>p.dayKey===key);
 const check=state.checkins[date]||{energy:3,soreness:1};
 const totalSets=done.reduce((n,h)=>n+completeSets(h),0);
 const streak=calculateStreak();
 $('#view-today').innerHTML=`
 <div class="hero"><div class="hero-grid"><div><div class="eyebrow">${fmtDate(date,{weekday:'long',month:'long',day:'numeric'})}</div><h1 id="todayTitle">${day.label}</h1><p>${key==='rest'?'A complete rest day. No secret punishment circuit, no guilt, no nonsense.':todayDone?'Today’s work is logged. Recovery is now part of the assignment.':'Choose a preset, keep the defaults, and change only what today actually requires.'}</p><div class="hero-actions">${key!=='rest'?`<button class="primary-btn" data-start="${dayPresets[0]?.id||''}">${state.currentWorkout?'Resume workout':'Start recommended'}</button><button class="secondary-btn" data-view="workouts">Browse presets</button>`:'<button class="primary-btn" disabled>Rest means rest</button>'}<button class="secondary-btn" data-view="settings">Settings</button></div></div><div class="day-orb"><span>${day.icon}</span></div></div></div>
 <div class="metric-grid"><div class="metric-card"><small>Workouts this week</small><strong>${done.length} / 6</strong><em>${done.length?Math.round(done.length/6*100):0}% scheduled</em></div><div class="metric-card"><small>Completed sets</small><strong>${totalSets}</strong><em>Quality beats theater</em></div><div class="metric-card"><small>Consistency streak</small><strong>${streak} days</strong><em>Completed workout days</em></div><div class="metric-card"><small>Baseline age</small><strong>${daysBetween(state.baselineStart,date)} days</strong><em>Progressions wait 28+</em></div></div>
 <div class="section"><div class="section-title"><div><h2>Weekly rhythm</h2><p>Sunday through Friday training, Saturday fully off.</p></div></div><div class="schedule-strip">${state.schedule.map((k,i)=>{const completed=done.some(h=>new Date(h.date+'T12:00:00').getDay()===i);return `<div class="schedule-day ${i===new Date().getDay()?'today':''} ${completed?'done':''}"><small>${WEEK_NAMES[i].slice(0,3)}</small><span>${DAYS[k].icon}</span><strong>${DAYS[k].short}</strong></div>`}).join('')}</div></div>
 <div class="section"><div class="section-title"><div><h2>Readiness check</h2><p>This changes recommendations, not your permanent defaults.</p></div></div><div class="surface"><div class="settings-grid"><div class="field"><label for="energyRange">Energy: <span id="energyLabel">${check.energy} / 5</span></label><input id="energyRange" type="range" min="1" max="5" value="${check.energy}"></div><div class="field"><label for="sorenessRange">Soreness: <span id="sorenessLabel">${check.soreness} / 4</span></label><input id="sorenessRange" type="range" min="0" max="4" value="${check.soreness}"></div></div><div id="readinessAdvice" class="tip-box">${readinessAdvice(check,key)}</div></div></div>
 <div class="section"><div class="section-title"><div><h2>${key==='rest'?'Tomorrow’s choices':'Today’s presets'}</h2><p>${key==='rest'?'Your arms await Sunday with their usual unreasonable optimism.':'Defaults remain your baseline unless you deliberately override them.'}</p></div>${key!=='rest'?'<button class="link-btn" data-view="workouts">See all</button>':''}</div><div class="card-grid">${(key==='rest'?[...PRESETS,...state.customPresets].filter(p=>p.dayKey==='arms'):dayPresets).slice(0,3).map(workoutCard).join('')}</div></div>`;
 bindCommon();
 const energy=$('#energyRange'),sore=$('#sorenessRange');
 if(energy) energy.addEventListener('input',()=>updateCheckin(date));
 if(sore) sore.addEventListener('input',()=>updateCheckin(date));
}
function readinessAdvice(c,key){if(key==='rest')return 'Do nothing strenuous. The app has issued a rare and legally binding order to relax.';if(c.soreness>=3||c.energy<=2)return 'Use the light preset, reduce sets, or substitute recovery cardio. Today is not a character test.';if(c.soreness===2)return 'The base workout is available, but keep 2–4 clean reps in reserve and skip painful movements.';return 'Your normal preset is reasonable. Keep clean form and treat optional heavier sets as optional.'}
function updateCheckin(date){const energy=+$(`#energyRange`).value,soreness=+$(`#sorenessRange`).value;state.checkins[date]={energy,soreness};saveState();$('#energyLabel').textContent=`${energy} / 5`;$('#sorenessLabel').textContent=`${soreness} / 4`;$('#readinessAdvice').textContent=readinessAdvice({energy,soreness},dayKeyToday())}
function workoutCard(p){const day=DAYS[p.dayKey];return `<article class="workout-card"><div class="top"><div class="icon">${day.icon}</div><span class="badge">${p.intensity}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.subtitle)}</p><footer><span>${p.exercises.length} exercises · ${totalPlannedSets(p)} sets</span><button data-start="${p.id}">Start →</button></footer></article>`}

function renderWorkouts(){
 const all=[...PRESETS,...state.customPresets];const list=all.filter(p=>p.dayKey===activeWorkoutTab);
 $('#view-workouts').innerHTML=`<div class="page-head"><div><div class="eyebrow">Preset library</div><h1 id="workoutsTitle">Choose the plan, not chaos</h1><p>Every main lifting day alternates its paired muscle groups. Your base workouts preserve the weights and reps we already established.</p></div><button class="secondary-btn" data-view="build">Build custom</button></div><div class="tabs">${DAY_ORDER.filter(k=>k!=='rest').map(k=>`<button class="tab ${k===activeWorkoutTab?'active':''}" data-workout-tab="${k}">${DAYS[k].icon} ${DAYS[k].short}</button>`).join('')}</div><div class="card-grid">${list.map(workoutCard).join('')}</div>`;
 bindCommon();$$('[data-workout-tab]').forEach(b=>b.addEventListener('click',()=>{activeWorkoutTab=b.dataset.workoutTab;renderWorkouts()}));
}

function initBuilder(dayKey='arms'){const groups=DAYS[dayKey].groups;const candidates=EXERCISES.filter(e=>groups.includes(e.group));builder={dayKey,name:`My Custom ${DAYS[dayKey].short}`,slots:Array.from({length:10},(_,i)=>{const group=groups[i%2]||groups[0];const e=candidates.find(x=>x.group===group)||candidates[0];return {group,id:e?.id||'',sets:clone(e?.defaultSets||[])}})}}
function renderBuild(){if(!builder.slots.length)initBuilder(builder.dayKey);
 $('#view-build').innerHTML=`<div class="page-head"><div><div class="eyebrow">Custom builder</div><h1 id="buildTitle">Build ten deliberate exercises</h1><p>The order alternates muscle groups automatically. You can change every exercise, weight, rep target, or timed interval before saving.</p></div></div><div class="builder-layout"><aside class="surface builder-sidebar"><div class="field"><label for="builderDay">Workout category</label><select id="builderDay">${DAY_ORDER.filter(k=>k!=='rest').map(k=>`<option value="${k}" ${k===builder.dayKey?'selected':''}>${DAYS[k].label}</option>`).join('')}</select></div><div class="field"><label for="builderName">Preset name</label><input id="builderName" value="${esc(builder.name)}" maxlength="45"></div><p class="tip-box">Saving creates a personal preset. It does not overwrite the built-in routines.</p><button id="saveBuilder" class="primary-btn" style="width:100%">Save custom preset</button><button id="resetBuilder" class="secondary-btn" style="width:100%;margin-top:8px">Reset builder</button></aside><div class="slot-list">${builder.slots.map((s,i)=>builderSlot(s,i)).join('')}</div></div>`;
 $('#builderDay').addEventListener('change',e=>{initBuilder(e.target.value);renderBuild()});$('#builderName').addEventListener('input',e=>builder.name=e.target.value);
 $$('.slot-exercise').forEach(sel=>sel.addEventListener('change',e=>{const i=+e.target.dataset.i,ex=EXERCISE_MAP[e.target.value];builder.slots[i].id=ex.id;builder.slots[i].sets=clone(ex.defaultSets);renderBuild()}));
 $$('.builder-set-input').forEach(inp=>inp.addEventListener('input',e=>{const i=+e.target.dataset.i,j=+e.target.dataset.j,key=e.target.dataset.key;let v=e.target.value;if(key!=='weight'||v!=='BW')v=+v;builder.slots[i].sets[j][key]=v}));
 $('#saveBuilder').addEventListener('click',saveBuilderPreset);$('#resetBuilder').addEventListener('click',()=>{initBuilder(builder.dayKey);renderBuild()});
}
function builderSlot(slot,i){const groups=DAYS[builder.dayKey].groups;const group=groups[i%2]||groups[0];slot.group=group;const opts=EXERCISES.filter(e=>builder.dayKey==='support'?e.group!=='Cardio':['Cardio'].includes(group)?e.group==='Cardio':e.group===group);const e=EXERCISE_MAP[slot.id]||opts[0];if(e&&slot.id!==e.id){slot.id=e.id;slot.sets=clone(e.defaultSets)}return `<article class="builder-slot"><div class="slot-head"><div class="slot-num">${i+1}</div><div><div class="slot-group">${group}</div><select class="slot-exercise field-input" data-i="${i}" style="margin-top:5px;width:100%;background:var(--panel-2);border:1px solid var(--line);border-radius:10px;padding:9px">${opts.map(x=>`<option value="${x.id}" ${x.id===slot.id?'selected':''}>${x.name}</option>`).join('')}</select></div><span class="badge">${e?.unit==='bodyweight'?'BW':e?.unit||''}</span></div><div class="slot-sets">${slot.sets.map((s,j)=>`<div class="mini-set"><small>Set ${j+1}</small><div class="mini-set-grid">${s.seconds!=null?`<input class="builder-set-input" data-i="${i}" data-j="${j}" data-key="seconds" type="number" min="5" value="${s.seconds}"><span style="align-self:center;color:var(--muted);font-size:.75rem">seconds</span>`:`<input class="builder-set-input" data-i="${i}" data-j="${j}" data-key="weight" type="text" value="${s.weight}" aria-label="Weight"><input class="builder-set-input" data-i="${i}" data-j="${j}" data-key="reps" type="number" min="1" value="${s.reps}" aria-label="Reps">`}</div></div>`).join('')}</div></article>`}
function saveBuilderPreset(){if(!builder.name.trim())return toast('Give the preset a name.');const p={id:'custom-'+uid(),dayKey:builder.dayKey,name:builder.name.trim(),subtitle:'Personal ten-exercise preset.',intensity:'Custom',custom:true,rounds:builder.dayKey==='cardio'?2:1,roundRest:builder.dayKey==='cardio'?90:0,exercises:builder.slots.map(s=>({id:s.id,sets:clone(s.sets)}))};state.customPresets.push(p);saveState();toast('Custom preset saved.');activeWorkoutTab=builder.dayKey;navigate('workouts')}

function renderHistory(){
 const items=[...state.history].sort((a,b)=>b.date.localeCompare(a.date)||b.startedAt.localeCompare(a.startedAt));
 $('#view-history').innerHTML=`<div class="page-head"><div><div class="eyebrow">Workout archive</div><h1 id="historyTitle">Your actual work</h1><p>Planned numbers are useful. Completed numbers are evidence.</p></div></div>${items.length?`<div class="history-list">${items.map(historyRow).join('')}</div>`:`<div class="empty"><span>◷</span>No completed workouts yet. A pristine archive, tragically.</div>`}`;
 $$('[data-history]').forEach(b=>b.addEventListener('click',()=>showHistory(b.dataset.history)));
}
function historyRow(h){const d=new Date(h.date+'T12:00:00'),day=DAYS[h.dayKey]||DAYS.support;return `<article class="history-row"><div class="history-date"><div><strong>${d.getDate()}</strong><small>${d.toLocaleString('en-US',{month:'short'})}</small></div></div><div><h3>${day.icon} ${esc(h.name)}</h3><p>${completeSets(h)} sets · ${workoutDuration(h)} min · ${h.painLevel||0}/4 pain</p></div><button data-history="${h.id}">Details →</button></article>`}
function showHistory(id){const h=state.history.find(x=>x.id===id);if(!h)return;const dlg=$('#detailsDialog');dlg.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${fmtDate(h.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</div><h2>${esc(h.name)}</h2></div><button class="close-btn">×</button></div><div class="metric-grid" style="grid-template-columns:repeat(3,1fr)"><div class="metric-card"><small>Sets</small><strong>${completeSets(h)}</strong></div><div class="metric-card"><small>Minutes</small><strong>${workoutDuration(h)}</strong></div><div class="metric-card"><small>Effort</small><strong>${h.effort||'—'}</strong></div></div>${h.exercises.map((x,i)=>{const e=EXERCISE_MAP[x.id]||{name:x.name||'Exercise',group:''};return `<div class="detail-exercise"><header><strong>${i+1}. ${e.name}</strong><small>${e.group}</small></header><small>${x.sets.filter(s=>s.completed).map(s=>s.seconds!=null?`${s.actualSeconds||s.seconds} sec`:`${s.actualWeight==='BW'?'BW':s.actualWeight+' lb'} × ${s.actualReps}`).join(' · ')||'Skipped'}</small></div>`}).join('')}<div style="display:flex;gap:8px;margin-top:18px"><button class="secondary-btn" id="repeatHistory">Repeat workout</button><button class="danger-btn" id="deleteHistory">Delete</button></div>`;dlg.showModal();$('.close-btn',dlg).addEventListener('click',()=>dlg.close());$('#repeatHistory',dlg).addEventListener('click',()=>{startWorkoutFromHistory(h);dlg.close()});$('#deleteHistory',dlg).addEventListener('click',()=>{if(confirm('Delete this workout log?')){state.history=state.history.filter(x=>x.id!==id);saveState();dlg.close();renderHistory();toast('Workout deleted.')}})}

function renderProgress(){
 const hist=state.history;const baselineDays=daysBetween(state.baselineStart,todayISO());const candidates=progressionCandidates();const week=weekHistory();const groups={};week.forEach(h=>h.exercises.forEach(x=>{const g=(EXERCISE_MAP[x.id]||{}).group||'Other';groups[g]=(groups[g]||0)+x.sets.filter(s=>s.completed).length}));const max=Math.max(1,...Object.values(groups));
 $('#view-progress').innerHTML=`<div class="page-head"><div><div class="eyebrow">Conservative progression</div><h1 id="progressTitle">Earn the suggestion</h1><p>Weight increases stay locked until at least 28 baseline days and three successful logged sessions for the exercise.</p></div></div><div class="metric-grid"><div class="metric-card"><small>Baseline period</small><strong>${baselineDays} / 28</strong><em>${baselineDays>=28?'Review unlocked':'Defaults stay put'}</em></div><div class="metric-card"><small>Total workouts</small><strong>${hist.length}</strong><em>All recorded sessions</em></div><div class="metric-card"><small>This week</small><strong>${week.length}</strong><em>of 6 planned days</em></div><div class="metric-card"><small>Eligible reviews</small><strong>${candidates.length}</strong><em>Suggestions, never commands</em></div></div><div class="progress-grid"><section class="surface"><div class="section-title"><div><h2>Weekly muscle-group sets</h2><p>Completed sets only.</p></div></div>${Object.keys(groups).length?`<div class="bar-list">${Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([g,n])=>`<div class="bar-row"><header><span>${g}</span><strong>${n}</strong></header><div class="bar-track"><div class="bar-fill" style="width:${Math.round(n/max*100)}%"></div></div></div>`).join('')}</div>`:'<div class="empty"><span>↗</span>Complete workouts to reveal the week.</div>'}</section><section class="surface"><div class="section-title"><div><h2>Progression review</h2><p>Rep progression comes before a risky weight jump.</p></div></div>${candidates.length?candidates.map(c=>`<div class="candidate"><strong>${c.name}</strong><small>${c.message}</small></div>`).join(''):`<div class="empty"><span>🔒</span>${baselineDays<28?`${28-baselineDays} baseline days remain before suggestions begin.`:'No exercise has three qualifying sessions yet.'}</div>`}</section></div>`;
}
function progressionCandidates(){if(daysBetween(state.baselineStart,todayISO())<28)return[];const map={};state.history.forEach(h=>h.exercises.forEach(x=>{const e=EXERCISE_MAP[x.id];if(!e||h.painLevel>1)return;const completed=x.sets.filter(s=>s.completed&&s.seconds==null);if(!completed.length)return;(map[x.id]??=[]).push(completed)}));return Object.entries(map).filter(([,sessions])=>sessions.length>=3).flatMap(([id,sessions])=>{const e=EXERCISE_MAP[id],recent=sessions.slice(-3);const met=recent.every(ss=>ss.every(s=>+s.actualReps>=+s.reps));if(!met)return[];const maxW=Math.max(...recent.flat().map(s=>s.actualWeight==='BW'?0:+s.actualWeight||0));let msg=maxW>=20&&['Biceps','Triceps','Shoulders'].includes(e.group)?'Keep the same weight and add 1–2 clean reps before considering the large jump to 30 lb.':`You met every target in three recent sessions. Consider adding one rep per set, a pause, or a small weight increase only if available.`;return [{name:e.name,message:msg}]})}

function renderSettings(){
 $('#view-settings').innerHTML=`<div class="page-head"><div><div class="eyebrow">Local and private</div><h1 id="settingsTitle">Settings & backup</h1><p>Your workout data stays in this browser unless you export it. The app has no account and no server watching you struggle through lateral raises.</p></div></div><div class="settings-grid"><section class="surface"><div class="section-title"><div><h2>App behavior</h2></div></div><div class="setting-row"><div><strong>Automatic rest timer</strong><p>Start the exercise timer after a completed set.</p></div><label class="switch"><input id="autoTimer" type="checkbox" ${state.settings.autoTimer?'checked':''}><span class="slider"></span></label></div><div class="setting-row"><div><strong>Theme</strong><p>Dark or light, because retinas apparently deserve representation.</p></div><button id="themeSetting" class="secondary-btn">${state.settings.theme==='dark'?'Use light':'Use dark'}</button></div><div class="setting-row"><div><strong>Baseline began</strong><p>Progression suggestions unlock after 28 days.</p></div><strong>${fmtDate(state.baselineStart,{month:'short',day:'numeric',year:'numeric'})}</strong></div></section><section class="surface"><div class="section-title"><div><h2>Data</h2></div></div><div style="display:grid;gap:9px"><button id="pdfBtn" class="primary-btn">Export complete PDF statement</button><button id="exportBtn" class="secondary-btn">Export JSON backup</button><button id="importBtn" class="secondary-btn">Import backup</button><button id="csvBtn" class="secondary-btn">Export history CSV</button><button id="resetBtn" class="danger-btn">Reset all app data</button></div><p style="color:var(--muted);font-size:.82rem;line-height:1.5;margin-top:15px">The PDF statement includes every workout, set, readiness check-in, custom preset, active workout, schedule, and setting. Keep JSON backups for restoring the app.</p></section><section class="surface"><div class="section-title"><div><h2>Equipment profile</h2><p>Used by every preset and builder filter.</p></div></div><div class="badge">Bench</div> <div class="badge">Bodyweight</div><div style="margin-top:10px;display:flex;gap:7px;flex-wrap:wrap">${[5,10,15,20,30].map(w=>`<span class="badge">${w} lb dumbbells</span>`).join('')}</div></section><section class="surface"><div class="section-title"><div><h2>Install</h2><p>Version ${APP_VERSION} · offline-first PWA</p></div></div><div id="installStatus" class="tip-box" style="margin-bottom:10px">Checking install readiness…</div><button id="installSettings" class="secondary-btn" style="width:100%">Install ForgeFit</button><button id="checkInstall" class="secondary-btn" style="width:100%;margin-top:8px">Check install readiness</button><p style="color:var(--muted);font-size:.82rem;line-height:1.5">A true Android installation appears in the app drawer and launches without Chrome's address bar. A plain shortcut does not.</p></section></div>`;
 $('#autoTimer').addEventListener('change',e=>{state.settings.autoTimer=e.target.checked;saveState()});$('#themeSetting').addEventListener('click',toggleTheme);$('#pdfBtn').addEventListener('click',exportPDFStatement);$('#exportBtn').addEventListener('click',exportJSON);$('#importBtn').addEventListener('click',()=>$('#importInput').click());$('#csvBtn').addEventListener('click',exportCSV);$('#resetBtn').addEventListener('click',resetAll);$('#installSettings').addEventListener('click',installApp);$('#checkInstall').addEventListener('click',checkInstallReadiness);updateInstallUI();
}

function instantiateWorkout(p){const makeExercise=(item,round=null,setOverride=null)=>{const e=EXERCISE_MAP[item.id];const source=setOverride?[setOverride]:setsFor(item);return {id:item.id,name:e?.name||item.id,round,sets:source.map(s=>({...s,actualWeight:s.weight,actualReps:s.reps,actualSeconds:s.seconds,completed:false})),pain:false}};let workoutExercises;if(p.dayKey==='cardio'&&(p.rounds||1)>1){workoutExercises=[];for(let r=0;r<p.rounds;r++)p.exercises.forEach(item=>{const planned=setsFor(item);workoutExercises.push(makeExercise(item,r+1,planned[r]||planned[0]))})}else workoutExercises=p.exercises.map(item=>makeExercise(item));return {id:uid(),presetId:p.id,dayKey:p.dayKey,name:p.name,date:todayISO(),startedAt:new Date().toISOString(),currentIndex:0,painLevel:0,effort:'Moderate',rounds:p.rounds||1,roundRest:p.roundRest||0,exercises:workoutExercises}}
function startWorkout(id){if(state.currentWorkout){openRunner();return}const p=presetById(id);if(!p)return toast('Preset not found.');state.currentWorkout=instantiateWorkout(p);saveState();openRunner()}
function startWorkoutFromHistory(h){if(state.currentWorkout&&!confirm('Replace the unfinished workout?'))return;state.currentWorkout={...clone(h),id:uid(),date:todayISO(),startedAt:new Date().toISOString(),finishedAt:null,durationSec:null,currentIndex:0,exercises:h.exercises.map(x=>({...x,sets:x.sets.map(s=>({...s,completed:false}))}))};saveState();openRunner()}
function openRunner(){const dlg=$('#runnerDialog');renderRunner();if(!dlg.open)dlg.showModal()}
function renderRunner(){const w=state.currentWorkout;if(!w)return;const dlg=$('#runnerDialog'),i=w.currentIndex,x=w.exercises[i],e=EXERCISE_MAP[x.id]||{name:x.name,group:'Exercise',tip:'Use controlled form.',rest:75,unit:''};const allDone=w.exercises.every(y=>y.sets.every(s=>s.completed));if(allDone)return renderFinish();const completedTotal=w.exercises.reduce((n,y)=>n+y.sets.filter(s=>s.completed).length,0),allTotal=w.exercises.reduce((n,y)=>n+y.sets.length,0);dlg.innerHTML=`<div class="runner-shell"><header class="runner-top"><div class="runner-topline"><div><div class="eyebrow">${esc(w.name)}</div><strong>${i+1} of ${w.exercises.length}</strong></div><button id="exitRunner" class="close-btn">×</button></div><div class="runner-progress"><div style="width:${Math.round(completedTotal/allTotal*100)}%"></div></div></header><div class="runner-body"><div class="exercise-hero"><div class="exercise-index">${i+1}</div><div><div class="eyebrow">${x.round?`Round ${x.round} · `:''}${e.group}</div><h2>${e.name}</h2><p>${e.equipment} · ${e.unit==='each'?'Weight per hand':e.unit==='single'?'One dumbbell per working side':e.unit==='total'?'One total dumbbell':e.unit==='bodyweight'?'Bodyweight':'Timed'}</p></div></div><div class="tip-box">${e.tip}</div><div class="set-table">${x.sets.map((s,j)=>setRow(s,j,e)).join('')}</div><div class="pain-row"><button id="painToggle" class="pain-chip ${x.pain?'active':''}">${x.pain?'⚠ Pain noted':'Note pain'}</button><button id="replaceExercise" class="pain-chip">Replace exercise</button><button id="skipExercise" class="pain-chip">Skip exercise</button></div></div><footer class="runner-nav"><button id="prevExercise" class="secondary-btn" ${i===0?'disabled':''}>← Previous</button><div id="timerPill" class="timer-pill">Rest <strong id="timerValue">Ready</strong></div><button id="nextExercise" class="primary-btn">${i===w.exercises.length-1?'Review':'Next →'}</button></footer></div>`;
 $('#exitRunner').addEventListener('click',()=>dlg.close());$$('.set-row').forEach(row=>bindSetRow(row,e));$('#prevExercise').addEventListener('click',()=>{w.currentIndex--;saveState();renderRunner()});$('#nextExercise').addEventListener('click',()=>{if(i<w.exercises.length-1){w.currentIndex++;saveState();renderRunner()}else{renderFinish()}});$('#painToggle').addEventListener('click',()=>{x.pain=!x.pain;if(x.pain)w.painLevel=Math.max(w.painLevel,2);saveState();renderRunner()});$('#skipExercise').addEventListener('click',()=>{x.sets.forEach(s=>s.skipped=true);if(i<w.exercises.length-1)w.currentIndex++;saveState();renderRunner()});$('#replaceExercise').addEventListener('click',()=>replaceExercise(i));
}
function setRow(s,j,e){const timed=s.seconds!=null;return `<div class="set-row ${s.completed?'completed':''}" data-set="${j}"><div class="set-number">${j+1}</div>${timed?`<div><label>Target</label><input value="${s.seconds} sec" disabled></div><div><label>Actual seconds</label><input class="actual-seconds" type="number" min="1" value="${s.actualSeconds??s.seconds}"></div>`:`<div><label>Weight (${e.unit==='each'?'each':e.unit==='bodyweight'?'BW':'lb'})</label><input class="actual-weight" type="text" value="${s.actualWeight}"></div><div><label>Reps / target ${s.reps}</label><input class="actual-reps" type="number" min="0" value="${s.actualReps}"></div>`}<button class="check-set" aria-label="Mark set complete">${s.completed?'✓':'○'}</button></div>`}
function bindSetRow(row,e){const j=+row.dataset.set,s=state.currentWorkout.exercises[state.currentWorkout.currentIndex].sets[j];$('.actual-weight',row)?.addEventListener('input',ev=>{s.actualWeight=ev.target.value;saveState()});$('.actual-reps',row)?.addEventListener('input',ev=>{s.actualReps=+ev.target.value;saveState()});$('.actual-seconds',row)?.addEventListener('input',ev=>{s.actualSeconds=+ev.target.value;saveState()});$('.check-set',row).addEventListener('click',()=>{s.completed=!s.completed;s.completedAt=s.completed?new Date().toISOString():null;const w=state.currentWorkout,x=w.exercises[w.currentIndex],next=w.exercises[w.currentIndex+1];let rest=e.rest||75;if(s.completed&&next&&x.round&&next.round!==x.round)rest=w.roundRest||90;saveState();renderRunner();if(s.completed&&state.settings.autoTimer)startTimer(rest)})}
function startTimer(sec){clearInterval(timerInterval);let remaining=sec;const update=()=>{const el=$('#timerValue');if(el)el.textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;if(remaining--<=0){clearInterval(timerInterval);if(el)el.textContent='Go';try{navigator.vibrate?.(150)}catch{}}};update();timerInterval=setInterval(update,1000)}
function replaceExercise(index){const w=state.currentWorkout,current=w.exercises[index],old=EXERCISE_MAP[current.id],groups=DAYS[w.dayKey]?.groups||[old.group];const expected=groups[index%2]||old.group;const choices=EXERCISES.filter(e=>w.dayKey==='support'?e.group!=='Cardio':e.group===expected);const dlg=$('#detailsDialog');dlg.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">Replace ${old.name}</div><h2>Choose ${expected}</h2></div><button class="close-btn">×</button></div><div class="field"><label for="replacementSelect">Exercise</label><select id="replacementSelect">${choices.map(e=>`<option value="${e.id}">${e.name}</option>`).join('')}</select></div><button id="confirmReplace" class="primary-btn" style="width:100%">Replace for today</button>`;dlg.showModal();$('.close-btn',dlg).addEventListener('click',()=>dlg.close());$('#confirmReplace',dlg).addEventListener('click',()=>{const e=EXERCISE_MAP[$('#replacementSelect',dlg).value];w.exercises[index]={id:e.id,name:e.name,sets:clone(e.defaultSets).map(s=>({...s,actualWeight:s.weight,actualReps:s.reps,actualSeconds:s.seconds,completed:false})),pain:false};saveState();dlg.close();renderRunner();toast('Exercise replaced for today.')})}
function renderFinish(){const w=state.currentWorkout,dlg=$('#runnerDialog'),sets=w.exercises.reduce((n,x)=>n+x.sets.filter(s=>s.completed).length,0),mins=Math.max(1,Math.round((Date.now()-new Date(w.startedAt))/60000));dlg.innerHTML=`<div class="finish-panel"><div class="big-check">✓</div><div class="eyebrow">Workout complete</div><h2>${esc(w.name)}</h2><p style="color:var(--muted)">The dumbbells have been temporarily defeated.</p><div class="finish-grid"><div><strong>${sets}</strong><small>sets</small></div><div><strong>${mins}</strong><small>minutes</small></div><div><strong>${w.exercises.filter(x=>x.pain).length}</strong><small>pain flags</small></div></div><div class="field" style="text-align:left"><label for="finishEffort">Overall effort</label><select id="finishEffort"><option>Easy</option><option selected>Moderate</option><option>Hard</option><option>Maximum</option></select></div><div class="field" style="text-align:left"><label for="finishPain">Overall pain: <span id="finishPainLabel">${w.painLevel||0} / 4</span></label><input id="finishPain" type="range" min="0" max="4" value="${w.painLevel||0}"></div><button id="saveWorkout" class="primary-btn" style="width:100%">Save workout</button><button id="discardWorkout" class="secondary-btn" style="width:100%;margin-top:8px">Discard</button></div>`;$('#finishPain').addEventListener('input',e=>$('#finishPainLabel').textContent=`${e.target.value} / 4`);$('#saveWorkout').addEventListener('click',finishWorkout);$('#discardWorkout').addEventListener('click',()=>{if(confirm('Discard this workout?')){state.currentWorkout=null;saveState();dlg.close();renderToday()}})}
function finishWorkout(){const w=state.currentWorkout;w.finishedAt=new Date().toISOString();w.durationSec=Math.round((new Date(w.finishedAt)-new Date(w.startedAt))/1000);w.effort=$('#finishEffort').value;w.painLevel=+$('#finishPain').value;state.history.push(clone(w));state.currentWorkout=null;saveState();$('#runnerDialog').close();toast('Workout saved.');navigate('today')}

function calculateStreak(){if(!state.history.length)return 0;const dates=[...new Set(state.history.map(h=>h.date))].sort().reverse();let streak=0,d=new Date();for(let i=0;i<370;i++){const iso=d.toISOString().slice(0,10),dow=d.getDay();if(dow===6){d.setDate(d.getDate()-1);continue}if(dates.includes(iso)){streak++;d.setDate(d.getDate()-1)}else if(iso===todayISO())d.setDate(d.getDate()-1);else break}return streak}
function daysBetween(a,b){return Math.max(0,Math.floor((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000))}
function bindCommon(){$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$$('[data-start]').forEach(b=>b.onclick=()=>startWorkout(b.dataset.start))}
function toggleTheme(){state.settings.theme=state.settings.theme==='dark'?'light':'dark';saveState();applyTheme();renderView(activeView)}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function exportPDFStatement(){const button=$('#pdfBtn');if(!window.ForgeFitPDF){alert('The PDF statement engine did not load. Reload ForgeFit and try again.');return}const oldText=button?.textContent;if(button){button.disabled=true;button.textContent='Building complete statement…'}try{const result=window.ForgeFitPDF.exportStatement({state:clone(state),exerciseMap:EXERCISE_MAP,days:DAYS,appVersion:APP_VERSION});toast(`PDF statement downloaded: ${result.pageCount} page${result.pageCount===1?'':'s'}.`)}catch(error){console.error('ForgeFit PDF export failed:',error);alert(`ForgeFit could not create the PDF statement: ${error.message}`)}finally{if(button){button.disabled=false;button.textContent=oldText||'Export complete PDF statement'}}}
function exportJSON(){download(`forgefit-backup-${todayISO()}.json`,JSON.stringify(state,null,2));toast('Backup exported.')}
function exportCSV(){const rows=[['Date','Workout','Day','Duration Minutes','Completed Sets','Effort','Pain']];state.history.forEach(h=>rows.push([h.date,h.name,DAYS[h.dayKey]?.label||h.dayKey,workoutDuration(h),completeSets(h),h.effort||'',h.painLevel||0]));download(`forgefit-history-${todayISO()}.csv`,rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv')}
function resetAll(){if(confirm('Erase every workout, custom preset, and setting from this browser?')){state=defaultState();saveState();applyTheme();navigate('today');toast('ForgeFit reset.')}}
function isStandalone(){return window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true}
function installStatusText(){if(isStandalone())return 'Installed correctly: ForgeFit is running in standalone mode.';if(!window.isSecureContext)return 'Not installable here: open the HTTPS GitHub Pages address, not a local file or repository preview.';if(!('serviceWorker' in navigator))return 'This browser does not support the service worker needed for offline app behavior.';if(deferredInstallPrompt)return 'Ready to install as a standalone Android app.';return 'Chrome has not offered installation yet. Tap the page once, leave it open for at least 30 seconds, then reload and use this button or Chrome’s menu.'}
function updateInstallUI(){const installed=isStandalone(),top=$('#installBtn'),settings=$('#installSettings'),status=$('#installStatus');if(top){top.textContent=installed?'Installed':'Install app';top.classList.toggle('hidden',installed)}if(settings){settings.textContent=installed?'ForgeFit is installed':'Install ForgeFit';settings.disabled=installed}if(status)status.textContent=installStatusText()}
async function checkInstallReadiness(){updateInstallUI();if(!window.isSecureContext){toast('Use the HTTPS GitHub Pages URL.');return}try{const manifestLink=document.querySelector('link[rel="manifest"]');const manifestResponse=await fetch(manifestLink.href,{cache:'no-store'});if(!manifestResponse.ok)throw new Error(`Manifest returned ${manifestResponse.status}`);const manifest=await manifestResponse.json();const sizes=(manifest.icons||[]).map(icon=>icon.sizes);const required=manifest.name||manifest.short_name;const validDisplay=['standalone','fullscreen','minimal-ui','window-controls-overlay'].includes(manifest.display);if(!required||!manifest.start_url||!validDisplay||!sizes.includes('192x192')||!sizes.includes('512x512'))throw new Error('Manifest is missing an install requirement');const registration=await navigator.serviceWorker.getRegistration('./');if(!registration)throw new Error('Service worker is not registered yet');toast(deferredInstallPrompt?'ForgeFit is ready to install.':'Core PWA checks passed. Reload once, then check Chrome’s menu.')}catch(error){console.error(error);toast(`Install check failed: ${error.message}`)}updateInstallUI()}
async function installApp(){if(isStandalone()){toast('ForgeFit is already installed.');return}if(deferredInstallPrompt){deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;if(choice.outcome==='accepted')toast('Installing ForgeFit…');deferredInstallPrompt=null;updateInstallUI();return}await checkInstallReadiness()}

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;updateInstallUI()});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;updateInstallUI();toast('ForgeFit installed as its own app.')});
window.matchMedia('(display-mode: standalone)').addEventListener?.('change',updateInstallUI);
$('#themeBtn').addEventListener('click',toggleTheme);$('#installBtn').addEventListener('click',installApp);$$('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
$('#importInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const imported=JSON.parse(await file.text());if(!imported.history||!imported.settings)throw new Error('Invalid');state={...defaultState(),...imported,version:APP_VERSION};saveState();applyTheme();navigate('today');toast('Backup imported.')}catch{alert('That file is not a valid ForgeFit backup.')}e.target.value=''});
if('serviceWorker' in navigator)window.addEventListener('load',async()=>{try{const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});await registration.update();await navigator.serviceWorker.ready;updateInstallUI()}catch(error){console.error('ForgeFit service worker failed:',error);updateInstallUI()}});
applyTheme();updateInstallUI();const requestedView=new URLSearchParams(location.search).get('view');if(['today','workouts','build','history','progress','settings'].includes(requestedView))navigate(requestedView);else renderToday();if(state.currentWorkout)toast('Unfinished workout ready to resume.');
